/**
 * Hono application of the MPP provider.
 *
 * Routes:
 *   GET /healthz       — free, liveness probe
 *   GET /v1/search     — paid (intent `charge`)
 *   GET /metrics       — bearer-protected Prometheus export (if metrics are provided)
 *   GET /openapi.json  — discovery document, generated by mppx
 *
 * Discovery source: https://mpp.dev/advanced/discovery
 * ("You serve a standard OpenAPI 3.1 document at /openapi.json with
 *   x-payment-info extensions"), `discovery(app, mppx, …)` helper from mppx/hono.
 */
import { Hono } from 'hono'
import { bearerAuth } from 'hono/bearer-auth'
import { BodyDigest, Credential } from 'mppx'
import { discovery } from 'mppx/hono'

import type { Metrics } from '../observability/metrics.ts'
import { analyze } from './analyze.ts'
import type { Config } from './config.ts'
import { createPayment, type Payment } from './payment.ts'
import { search } from './search.ts'

export function createApp(
  config: Config,
  payment: Payment = createPayment(config),
  metrics?: Metrics,
) {
  const app = new Hono()

  // Settlement latency: only requests carrying a Credential
  // (`Authorization: Payment …`) are timed. The header is only tested,
  // never read nor logged.
  if (metrics)
    app.use('*', async (c, next) => {
      const paid = c.req.header('Authorization')?.startsWith('Payment ') === true
      const start = performance.now()
      await next()
      if (paid)
        metrics.settlement.observe(
          { status: c.res.status === 200 ? 'success' : 'failed' },
          (performance.now() - start) / 1000,
        )
    })

  /**
   * A 200 response carrying a Receipt must not be cached by a shared
   * intermediary. mppx sets `no-store` on 402s by itself, but not `private`
   * on 200s — that is our job.
   * Source: https://mpp.dev/advanced/security
   * "Send Cache-Control: private on successful responses that include
   *   Payment-Receipt."
   */
  app.use('*', async (c, next) => {
    await next()
    if (c.res.status === 200 && c.res.headers.has('Payment-Receipt'))
      c.res.headers.set('Cache-Control', 'private')
  })

  // Fail-closed: without `metricsToken`, the route does not exist (404).
  // The token is compared in constant time and is never logged.
  if (metrics && config.metricsToken)
    app.get('/metrics', bearerAuth({ token: config.metricsToken }), async (c) =>
      c.body(await metrics.render(), 200, { 'Content-Type': metrics.contentType }),
    )

  app.get('/healthz', (c) => c.json({ status: 'ok', realm: config.realm }))

  app.get(
    '/v1/search',
    payment.charge({
      amount: config.searchPrice,
      description: 'Document search — 1 request',
    }),
    (c) => {
      const query = c.req.query('q') ?? ''
      // Payment is verified: the Credential is still on the request.
      // `source` is a DID (did:pkh:eip155:42431:0x…).
      // Source: https://mpp.dev/sdk/typescript/middlewares/hono § Identifying the payer
      const header = c.req.header('Authorization')
      const payer = header ? Credential.deserialize(header).source : undefined
      return c.json({ query, payer, results: search(query) })
    },
  )

  /**
   * POST route: the body is **bound** to the Challenge.
   *
   * ⚠️ The TypeScript mppx server does not expose a `body`/`digest` option
   * on the middleware (unlike the Python SDK). We therefore implement the
   * binding through `scope`, which mppx folds into `meta` → `opaque` → the
   * Challenge HMAC. A body modified after issuance produces a different
   * scope, hence a different Challenge id: the Credential no longer verifies.
   *
   * Source of the requirement: https://mpp.dev/advanced/security
   * "Include a digest parameter for POST, PUT, and PATCH requests so clients
   *   cannot change the request body after receiving a Challenge."
   */
  app.post('/v1/analyze', async (c, next) => {
    // `clone()`: we read the body without consuming it for the rest of the chain.
    const raw = await c.req.raw.clone().text()
    const middleware = payment.charge({
      amount: config.analyzePrice,
      description: 'Document analysis — 1 request',
      scope: `POST /v1/analyze#${BodyDigest.compute(raw)}`,
    })
    return middleware(c, next)
  })

  app.post('/v1/analyze', async (c) => {
    const body = (await c.req.json().catch(() => ({}))) as { text?: unknown }
    const header = c.req.header('Authorization')
    const payer = header ? Credential.deserialize(header).source : undefined
    return c.json({ payer, analysis: analyze(typeof body.text === 'string' ? body.text : '') })
  })

  discovery(app, payment, {
    auto: true,
    info: { title: 'Agentic Research Marketplace', version: '0.1.0' },
  })

  return app
}

export type App = ReturnType<typeof createApp>
